# Bank zadań autorskich — etap 2: wypracowania (partia 4: tematy przekrojowe i drugie tematy do epok).
BANK = {}

M = 'Wypracowanie (wypowiedź argumentacyjna). Zadanie autorskie IndexLab w formacie egzaminu maturalnego od 2023 r. Twoja wypowiedź powinna liczyć minimum 300 wyrazów.'

BANK['umiejetnosci'] = [
 B('Wypracowanie — przekrojowy: epidemie w dziejach', M,
   T('wypracowanie', 15, 'Wielkie epidemie zmieniały bieg historii w większym stopniu niż wojny. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, odwołując się do trzech epidemii z różnych epok.',
     'Modelowa odpowiedź (stanowisko: epidemie często zmieniały historię głębiej niż wojny, choć zwykle przyspieszały procesy już trwające).\n\n'
     'Historię zwykle opowiada się przez wojny, bitwy i traktaty. Tymczasem niewidzialni wrogowie — bakterie i wirusy — zabijali czasem więcej ludzi niż wszystkie wojny danej epoki. Uważam, że wielkie epidemie zmieniały bieg dziejów w stopniu porównywalnym z wojnami, a często większym, choć przeważnie przyspieszały zmiany, które już się zaczęły.\n\n'
     'Pierwszym przykładem jest czarna śmierć w połowie XIV w. W latach 1347–1351 dżuma zabiła prawdopodobnie od jednej trzeciej do połowy mieszkańców Europy. Skutki były głębsze niż skutki ówczesnych wojen, nawet wojny stuletniej: zabrakło rąk do pracy, więc chłopi na Zachodzie mogli domagać się niższych powinności, co przyspieszyło upadek poddaństwa. Wybuchały bunty (żakeria we Francji, powstanie Wata Tylera w Anglii), a w miastach szerzyły się pogromy Żydów oskarżanych o zatruwanie studni. Kryzys podważył też autorytet Kościoła, który nie potrafił wyjaśnić katastrofy.\n\n'
     'Drugim przykładem są epidemie w Ameryce w XVI w. Ospa, odra i grypa, przywiezione przez Europejczyków, zabiły zdecydowaną większość ludności rdzennej — w niektórych regionach nawet 90%. To epidemie, a nie same miecze konkwistadorów, przesądziły o upadku imperiów Azteków i Inków i o tym, że Ameryka stała się kontynentem zdominowanym przez przybyszów z Europy i niewolników z Afryki.\n\n'
     'Trzecim przykładem jest grypa hiszpanka (1918–1920), która zabiła na świecie kilkadziesiąt milionów ludzi — więcej niż I wojna światowa. Osłabiła armie w ostatnich miesiącach wojny i wstrząsnęła społeczeństwami. Jednak jej wpływ polityczny był mniejszy: o nowym ładzie świata zdecydowała wojna, a nie epidemia.\n\n'
     'Właśnie ten przykład pokazuje granice tezy. Wojny bezpośrednio zmieniały granice, ustroje i władców, a epidemie działały pośrednio, przez demografię i gospodarkę. Często też zbiegały się z wojnami — jak tyfus w czasie wojen napoleońskich czy dżuma w oblężonych miastach.\n\n'
     'Podsumowując, w przypadku czarnej śmierci i epidemii w Ameryce teza jest prawdziwa, bo choroby zmieniły strukturę społeczeństw na stulecia. W przypadku hiszpanki ważniejsza była wojna. Dlatego uważam, że teza jest prawdziwa częściowo, ale historycy zbyt często zapominają o roli epidemii.',
     'Plan: stanowisko „częściowo, ale epidemie niedoceniane” → czarna śmierć (1347–1351, skutki społeczne i religijne) → Ameryka XVI w. (ospa, upadek Azteków i Inków) → hiszpanka (1918–1920, więcej ofiar niż wojna, ale mniej skutków politycznych) → kontrargument (wojny zmieniały granice bezpośrednio) → wniosek.\n\nTypowe błędy: wybór epidemii z jednej epoki; podawanie liczby ofiar bez skutków. W temacie „trzy przykłady” każdy musi mieć osobny akapit.')),

 B('Wypracowanie — przekrojowy: wynalazki techniczne', M,
   T('wypracowanie', 15, 'Wynalazki techniczne zmieniały życie ludzi bardziej niż rewolucje polityczne. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, odwołując się do trzech wynalazków z różnych epok.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa).\n\n'
     'Rewolucje polityczne — angielska, francuska czy rosyjska — zmieniały władców i ustroje, ale często pozostawiały codzienne życie zwykłych ludzi niemal bez zmian. Uważam, że wynalazki techniczne zmieniały ludzkie życie głębiej i trwalej, bo dotykały każdego: sposobu pracy, komunikacji i zdobywania wiedzy.\n\n'
     'Pierwszym przykładem jest druk ruchomą czcionką, wynaleziony przez Jana Gutenberga około połowy XV w. Wcześniej książki przepisywano ręcznie i były dostępne dla nielicznych. Druk sprawił, że książki stały się tańsze i powszechniejsze, a wiedza szybciej się rozprzestrzeniała. Bez druku reformacja nie odniosłaby tak szybkiego sukcesu — pisma Lutra w ciągu kilku tygodni czytano w całych Niemczech. Druk przyczynił się też do rozwoju języków narodowych i nauki.\n\n'
     'Drugim przykładem jest maszyna parowa, udoskonalona przez Jamesa Watta w drugiej połowie XVIII w. Zapoczątkowała rewolucję przemysłową: pojawiły się fabryki, koleje i statki parowe. Miliony ludzi przeniosły się ze wsi do miast, zmieniły się rodzina, czas pracy i rytm życia. Powstała nowa klasa — robotnicy przemysłowi — a z nią nowe ideologie, jak socjalizm. Żadna rewolucja polityczna XVIII w. nie zmieniła życia tak wielu ludzi.\n\n'
     'Trzecim przykładem jest elektryczność i oparte na niej wynalazki z przełomu XIX i XX w.: żarówka (Edison, 1879), telefon (Bell, 1876), radio. Wydłużyły dzień pracy i nauki, umożliwiły natychmiastową komunikację na odległość, a w XX w. stały się podstawą przemysłu i życia domowego. Radio stało się zarazem narzędziem propagandy totalitarnych dyktatur.\n\n'
     'Zwolennicy przeciwnego poglądu przypominają, że rewolucje polityczne przyniosły prawa człowieka, równość wobec prawa i demokrację, bez których wynalazki mogłyby służyć wąskiej elicie. To ważny argument: to rewolucja francuska zniosła przywileje stanowe. Jednak nawet idee rewolucji rozprzestrzeniały się dzięki prasie drukowanej, a demokracja masowa nie byłaby możliwa bez kolei, telegrafu i powszechnej oświaty.\n\n'
     'Podsumowując, wynalazki techniczne — od druku, przez maszynę parową, po elektryczność — zmieniały codzienne życie ludzi głębiej niż rewolucje polityczne. Dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak” → druk (Gutenberg, reformacja, języki narodowe) → maszyna parowa (Watt, industrializacja, urbanizacja, klasa robotnicza) → elektryczność (żarówka, telefon, radio, propaganda) → kontrargument (prawa człowieka z rewolucji) → wniosek.\n\nTypowe błędy: wymienianie wynalazków bez wyjaśnienia, jak zmieniły życie; wybór trzech wynalazków z jednego stulecia.')),

 B('Wypracowanie — przekrojowy: przywileje szlacheckie', M,
   T('wypracowanie', 15, 'Przywileje szlacheckie z XIV–XVI w. w dłuższej perspektywie osłabiły państwo polskie. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, odwołując się do trzech wybranych przywilejów lub aktów prawnych.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa, choć w chwili wydania przywileje często służyły ważnym celom państwa).\n\n'
     'W XIV–XVI w. polscy królowie wydali szereg przywilejów, które stopniowo przekazały szlachcie decydujący wpływ na państwo. W momencie wydania każdy z nich miał uzasadnienie — zapewniał tron, pieniądze na wojnę albo poparcie elit. Uważam jednak, że w dłuższej perspektywie osłabiły one władzę centralną i przyczyniły się do kryzysu Rzeczypospolitej.\n\n'
     'Pierwszym przykładem jest przywilej koszycki (1374), wydany przez Ludwika Węgierskiego, by zapewnić tron jednej z córek. Zwalniał szlachtę z podatków z wyjątkiem niewielkiego poradlnego, a urzędy w ziemiach miały otrzymywać tylko miejscowi. Król zyskał sukcesję dla dynastii, ale skarb państwa stracił stały dochód, a każdy nowy podatek wymagał odtąd zgody szlachty.\n\n'
     'Drugim przykładem są przywileje cerekwicko-nieszawskie (1454), które Kazimierz Jagiellończyk wydał na początku wojny trzynastoletniej, by zdobyć wsparcie pospolitego ruszenia. Król zobowiązał się, że bez zgody sejmików nie będzie stanowił nowych praw ani zwoływał pospolitego ruszenia. Wzmocniło to sejmiki i rozwój parlamentaryzmu szlacheckiego, ale ograniczyło swobodę króla w sprawach wojny i prawa.\n\n'
     'Trzecim przykładem jest konstytucja Nihil novi (1505), która stanowiła, że nic nowego nie może być ustanowione bez zgody senatu i izby poselskiej. Ukształtowała ona monarchię sejmową. Gdy w XVII w. sejm zaczął być zrywany na mocy liberum veto, ta zasada sprawiła, że państwo nie mogło uchwalić podatków ani reform.\n\n'
     'Zwolennicy przeciwnego poglądu podkreślają, że przywileje zbudowały wyjątkowy w Europie ustrój, w którym kilka procent społeczeństwa miało prawa obywatelskie, a nietykalność osobista (neminem captivabimus, 1430/1433) chroniła przed samowolą władzy. To prawda — w XVI w. Rzeczpospolita była silna, a demokracja szlachecka nie musiała prowadzić do upadku. Jednak przywileje dotyczyły tylko szlachty, a mieszczanie i chłopi zostali odsunięci od wpływu na państwo.\n\n'
     'Warto też zauważyć, że w tym samym czasie w innych państwach — Francji czy Hiszpanii — władcy wzmacniali się kosztem stanów, budując monarchie absolutne ze stałym wojskiem i podatkami.\n\n'
     'Podsumowując, przywileje szlacheckie miały w chwili wydania racjonalne uzasadnienie i stworzyły oryginalny ustrój. W dłuższej perspektywie ograniczyły jednak skarb, władzę wykonawczą i możliwość reform, dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak, choć z uzasadnieniem w chwili wydania” → Koszyce 1374 (podatki, urzędy) → Cerekwica-Nieszawa 1454 (sejmiki, pospolite ruszenie) → Nihil novi 1505 (monarchia sejmowa → paraliż przy liberum veto) → kontrargument (wolności szlacheckie, neminem captivabimus) → wniosek.\n\nTypowe błędy: wyliczanie przywilejów bez skutków; mylenie dat; pisanie, że Nihil novi wprowadziło liberum veto.')),

 B('Wypracowanie — starożytność: potęga Rzymu', M,
   T('wypracowanie', 15, 'Rzym zawdzięczał swoją potęgę przede wszystkim armii. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt militarny, polityczno-prawny i kulturowy.',
     'Modelowa odpowiedź (stanowisko: armia była warunkiem podbojów, ale trwałość potęgi Rzymu zapewniły prawo, organizacja państwa i kultura).\n\n'
     'Rzym w ciągu kilku stuleci przeszedł drogę od małego miasta nad Tybrem do imperium obejmującego cały basen Morza Śródziemnego. Uważam, że armia była warunkiem koniecznym tej ekspansji, ale nie wystarczającym: potęga Rzymu przetrwała tak długo dzięki prawu, organizacji państwa i atrakcyjności kultury.\n\n'
     'W aspekcie militarnym armia rzymska była najlepiej zorganizowaną siłą starożytności. Legion, podzielony na kohorty i centurie, był elastyczny na polu bitwy. Żołnierzy cechowały dyscyplina, wyszkolenie i umiejętność budowy umocnionych obozów. Po reformie Gajusza Mariusza (koniec II w. p.n.e.) armia stała się zawodowa. To armia pokonała Kartaginę w wojnach punickich, podbiła Grecję, Galię (Cezar) i Egipt, a później broniła granic (limes). Rzymskie drogi budowano przede wszystkim z myślą o szybkim przemieszczaniu wojsk.\n\n'
     'W aspekcie polityczno-prawnym Rzym potrafił utrzymać podbite ziemie. Podzielił je na prowincje z namiestnikami, a podbitym ludom stopniowo nadawał prawa — od sojuszników w Italii po obywatelstwo, przyznane w 212 r. n.e. wszystkim wolnym mieszkańcom imperium (edykt Karakalli). Prawo rzymskie, oparte na zasadach takich jak równość obywateli wobec prawa, regulowało własność, umowy i spadki. To ono, a nie legiony, przetrwało upadek imperium i do dziś jest podstawą prawa cywilnego w Europie.\n\n'
     'W aspekcie kulturowym Rzym przyciągał. Romanizacja sprawiła, że elity podbitych ludów przyjmowały łacinę, budowały miasta z forum, łaźniami i amfiteatrami i chciały być Rzymianami. Rzym przejął i rozpowszechnił kulturę grecką, a później chrześcijaństwo. Pax Romana, czyli dwa stulecia względnego pokoju, sprzyjał handlowi i rozwojowi miast.\n\n'
     'Zwolennicy tezy podkreślają, że gdy armia słabła — w kryzysie III w. czy w V w. — imperium zaczynało się rozpadać. To prawda, ale słabnięcie armii było skutkiem głębszych problemów: kryzysu gospodarczego, walk o władzę i problemów z rekrutacją.\n\n'
     'Potęga Rzymu opierała się też na inżynierii: akweduktach, mostach i miastach budowanych według jednolitego planu, które ułatwiały życie mieszkańców prowincji.\n\n'
     'Podsumowując, armia zdobyła dla Rzymu imperium, ale prawo, organizacja państwa i kultura sprawiły, że trwało ono przez stulecia. Dlatego uważam tezę za tylko częściowo prawdziwą.',
     'Plan: stanowisko „częściowo” → militarny (legion, dyscyplina, Mariusz, podboje, limes, drogi) → polityczno-prawny (prowincje, obywatelstwo, 212 r., prawo rzymskie) → kulturowy (romanizacja, łacina, kultura grecka, pax Romana) → kontrargument (upadek wraz z armią) → wniosek.\n\nTypowe błędy: opisywanie tylko bitew; brak przykładów z różnych okresów (republika i cesarstwo).')),

 B('Wypracowanie — średniowiecze: papiestwo i cesarstwo', M,
   T('wypracowanie', 15, 'Rywalizacja papiestwa z cesarstwem w XI–XIII w. zakończyła się zwycięstwem papiestwa. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji trzy etapy tego sporu.',
     'Modelowa odpowiedź (stanowisko: papiestwo wygrało rywalizację w XIII w., ale było to zwycięstwo krótkotrwałe).\n\n'
     'W średniowieczu dwie władze rościły sobie prawo do kierowania chrześcijańskim światem: papież jako zwierzchnik Kościoła i cesarz jako następca władców Rzymu. Uważam, że w XIII w. papiestwo rzeczywiście wygrało tę rywalizację, ale jego zwycięstwo było krótkie — już w XIV w. popadło w zależność od króla Francji.\n\n'
     'Pierwszym etapem był spór o inwestyturę w drugiej połowie XI w. Papież Grzegorz VII w „Dictatus papae” ogłosił, że tylko papież może mianować biskupów i może nawet zdetronizować cesarza. Cesarz Henryk IV odpowiedział próbą złożenia papieża z urzędu, a ten ekskomunikował cesarza. W 1077 r. Henryk musiał upokorzyć się w Canossie, by uzyskać zdjęcie klątwy, choć później wygnał Grzegorza z Rzymu. Spór zakończył konkordat wormacki (1122): inwestyturę duchowną (pierścień i pastorał) przyznano papieżowi, a świecką — cesarzowi. Był to kompromis, ale korzystny dla papiestwa.\n\n'
     'Drugim etapem była walka z dynastią Hohenstaufów. Fryderyk I Barbarossa próbował podporządkować sobie Italię, ale przegrał z miastami lombardzkimi wspieranymi przez papieża pod Legnano (1176). Jego wnuk Fryderyk II walczył z papiestwem przez całe życie, był wielokrotnie ekskomunikowany, a sobór w Lyonie (1245) ogłosił jego detronizację. Po jego śmierci dynastia Hohenstaufów upadła, a cesarstwo pogrążyło się w bezkrólewiu.\n\n'
     'Trzecim etapem był szczyt potęgi papiestwa za Innocentego III (1198–1216), który decydował o wyborze cesarza, zmusił króla Anglii Jana bez Ziemi do uznania się lennikiem papieża i zwołał IV sobór laterański. Papiestwo stało się najważniejszą siłą polityczną Europy.\n\n'
     'Zwycięstwo okazało się jednak krótkotrwałe. Bonifacy VIII, głoszący w bulli „Unam sanctam” (1302) wyższość władzy papieskiej, przegrał spór z królem Francji Filipem IV Pięknym, a od 1309 r. papieże rezydowali w Awinionie. Pokonali cesarzy, ale ulegli silnym monarchiom narodowym.\n\n'
     'Wyrazem potęgi papiestwa były też wyprawy krzyżowe: to papież, a nie cesarz, wzywał rycerstwo Europy do walki i kierował tą wspólną akcją chrześcijaństwa.\n\n'
     'Podsumowując, w rywalizacji z cesarstwem papiestwo zwyciężyło — cesarstwo zostało osłabione, a Hohenstaufowie upadli. Dlatego teza jest prawdziwa, choć zwycięzca szybko utracił swoją przewagę.',
     'Plan: stanowisko „tak, ale krótkotrwale” → spór o inwestyturę (Grzegorz VII, Canossa 1077, Wormacja 1122) → Hohenstaufowie (Legnano 1176, Fryderyk II, Lyon 1245) → Innocenty III → kontrargument (Bonifacy VIII, Awinion) → wniosek.\n\nTypowe błędy: kończenie na Canossie (to nie był koniec sporu); mylenie konkordatu wormackiego z Wormacją z czasów Lutra (1521).')),

 B('Wypracowanie — XIX w.: powstanie styczniowe', M,
   T('wypracowanie', 15, 'Powstanie styczniowe, choć zakończyło się klęską, przyniosło Polakom trwałe korzyści. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, społeczny i kulturowy.',
     'Modelowa odpowiedź (stanowisko: teza jest częściowo prawdziwa — straty były ogromne, ale powstanie zmieniło społeczeństwo i pamięć narodową).\n\n'
     'Powstanie styczniowe wybuchło w nocy z 22 na 23 stycznia 1863 r. i trwało ponad rok. Zginęły dziesiątki tysięcy powstańców, tysiące zesłano na Syberię, a Królestwo Polskie straciło resztki autonomii. Uważam jednak, że choć bilans był tragiczny, powstanie przyniosło także trwałe zmiany, z których Polacy skorzystali w kolejnych dekadach.\n\n'
     'W aspekcie politycznym skutki były przede wszystkim negatywne. Po powstaniu zlikwidowano odrębność Królestwa („Kraj Przywiślański”), rozpoczęła się rusyfikacja administracji i szkół, a dobra uczestników skonfiskowano. Jednocześnie powstanie pokazało, że Polacy potrafią stworzyć państwo podziemne: Rząd Narodowy miał administrację, sądy, policję i ściągał podatki. Ta tradycja odżyła w czasie II wojny światowej.\n\n'
     'W aspekcie społecznym najważniejszym skutkiem było uwłaszczenie chłopów. Rząd Narodowy w manifeście z 22 stycznia ogłosił chłopów właścicielami ziemi, a car, by ich pozyskać, w 1864 r. przeprowadził uwłaszczenie na korzystnych warunkach. Chłopi stali się właścicielami, co otworzyło drogę do ich udziału w życiu narodowym. Ceną było osłabienie ziemiaństwa, które straciło część majątków i pozycję społeczną.\n\n'
     'W aspekcie kulturowym klęska zmieniła myślenie Polaków. Odrzucono romantyczną wiarę w zbrojny zryw i zwrócono się ku pozytywizmowi — pracy organicznej i pracy u podstaw. Jednocześnie pamięć o powstańcach — Traugutcie straconym na stokach Cytadeli, o kosynierach i partyzantach — stała się częścią tożsamości narodowej. Utrwalały ją obrazy Artura Grottgera, a później proza Orzeszkowej („Gloria victis”) i Żeromskiego. Weterani powstania byli w 1918 r. honorowani przez odrodzone państwo.\n\n'
     'Przeciwnicy tezy słusznie zauważają, że korzyści, takie jak uwłaszczenie, nastąpiłyby i bez powstania, a cena w ludziach i stratach była zbyt wysoka. Jednak uwłaszczenie w tak korzystnej dla chłopów formie było bezpośrednią odpowiedzią na politykę powstańców.\n\n'
     'Powstanie miało też wymiar międzynarodowy: wywołało falę sympatii we Francji i Wielkiej Brytanii, a jednocześnie zbliżyło Prusy do Rosji (konwencja Alvenslebena, 1863), co ułatwiło Bismarckowi zjednoczenie Niemiec bez sprzeciwu Petersburga.\n\n'
     'Podsumowując, powstanie styczniowe zakończyło się klęską militarną i polityczną, ale przyspieszyło przemiany społeczne i umocniło pamięć narodową. Dlatego teza jest częściowo prawdziwa.',
     'Plan: stanowisko „częściowo” → polityczny (represje, rusyfikacja / tradycja państwa podziemnego) → społeczny (dekrety Rządu Narodowego, ukaz 1864, osłabienie ziemiaństwa) → kulturowy (pozytywizm, pamięć, Grottger, „Gloria victis”, weterani 1918) → kontrargument → wniosek.\n\nTypowe błędy: opis przebiegu walk zamiast oceny skutków; mylenie uwłaszczenia w Królestwie (1864) z Galicją (1848).')),

 B('Wypracowanie — 1914–1918: droga do niepodległości', M,
   T('wypracowanie', 15, 'I wojna światowa stworzyła Polakom szansę na niepodległość, z której umiejętnie skorzystali. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt militarny, dyplomatyczny i polityczny.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa).\n\n'
     'Polacy od ponad stu lat czekali na wojnę, w której zaborcy staną przeciwko sobie. W 1914 r. Rosja walczyła z Niemcami i Austro-Węgrami, a cztery lata później wszystkie trzy państwa zaborcze poniosły klęskę lub pogrążyły się w rewolucji. Uważam, że Polacy dobrze wykorzystali tę wyjątkową sytuację, działając jednocześnie na kilku frontach — militarnym, dyplomatycznym i politycznym.\n\n'
     'W aspekcie militarnym Polacy stworzyli własne formacje. Józef Piłsudski wyprowadził w sierpniu 1914 r. Pierwszą Kompanię Kadrową, a Legiony Polskie walczyły u boku Austro-Węgier (bitwa pod Kostiuchnówką, 1916). Po odmowie złożenia przysięgi na wierność cesarzom (kryzys przysięgowy, 1917) Piłsudski trafił do Magdeburga, co uczyniło go symbolem niezależności. We Francji powstała Błękitna Armia gen. Józefa Hallera. Polskie oddziały były dowodem, że naród jest gotów walczyć o swoje państwo.\n\n'
     'W aspekcie dyplomatycznym obóz Romana Dmowskiego zabiegał o poparcie ententy. Komitet Narodowy Polski w Paryżu (1917) został uznany przez państwa zachodnie za przedstawiciela Polaków. Ignacy Jan Paderewski przekonał prezydenta USA Woodrowa Wilsona, który w orędziu (styczeń 1918) zapowiedział w punkcie 13. niepodległą Polskę z dostępem do morza. Po rewolucji w Rosji rząd bolszewicki uznał prawo Polaków do niepodległości.\n\n'
     'W aspekcie politycznym państwa centralne, chcąc pozyskać rekruta, wydały akt 5 listopada 1916 r., zapowiadający Królestwo Polskie. Powstała Rada Regencyjna i zalążki polskiej administracji, szkolnictwa i sądownictwa. Gdy w listopadzie 1918 r. Niemcy i Austro-Węgry się załamały, Polacy przejęli władzę: 11 listopada Rada Regencyjna przekazała dowództwo wojska Piłsudskiemu, który został Naczelnikiem Państwa.\n\n'
     'Można argumentować, że niepodległość była przede wszystkim skutkiem klęski zaborców, a nie zasługą Polaków. Klęska zaborców była warunkiem koniecznym — ale bez polskiego wojska, polskich instytucji i poparcia ententy ziemie polskie mogły trafić do innych państw albo stać się ich strefą wpływów.\n\n'
     'Ważna była też jedność w kluczowym momencie: w listopadzie 1918 r. rząd Jędrzeja Moraczewskiego, a w styczniu 1919 r. rząd Paderewskiego połączyły obóz Piłsudskiego z obozem Dmowskiego.\n\n'
     'Podsumowując, Polacy umiejętnie wykorzystali szansę stworzoną przez wojnę, łącząc różne orientacje polityczne. Dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak” → militarny (Kadrówka, Legiony, Kostiuchnówka, kryzys przysięgowy, Błękitna Armia) → dyplomatyczny (KNP 1917, Paderewski, 13. punkt Wilsona) → polityczny (akt 5 listopada, Rada Regencyjna, 11 listopada) → kontrargument (klęska zaborców) → wniosek.\n\nTypowe błędy: przypisywanie niepodległości jednej osobie lub jednej orientacji; pomijanie aktu 5 listopada. Uwaga: CKE w 2024 r. pytało o rolę Piłsudskiego — ten temat ćwiczy podobną wiedzę z innej strony.')),

 B('Wypracowanie — świat po 1945 r.: rozpad ZSRS', M,
   T('wypracowanie', 15, 'Rozpad Związku Sowieckiego w 1991 r. był skutkiem przede wszystkim jego słabości gospodarczej. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt gospodarczy, polityczny i narodowościowy.',
     'Modelowa odpowiedź (stanowisko: słabość gospodarcza była ważną przyczyną, ale o rozpadzie przesądziły czynniki polityczne i narodowościowe).\n\n'
     'W grudniu 1991 r. Związek Sowiecki przestał istnieć, a na jego miejscu powstało piętnaście niepodległych państw. Ten rozpad zaskoczył świat, bo jeszcze kilka lat wcześniej ZSRS uchodził za supermocarstwo. Uważam, że kryzys gospodarczy był ważną przyczyną upadku, ale nie główną — przesądziły o nim reformy polityczne Gorbaczowa i dążenia narodów do niepodległości.\n\n'
     'W aspekcie gospodarczym ZSRS był w głębokim kryzysie. Gospodarka centralnie planowana była nieefektywna, brakowało towarów konsumpcyjnych, a rolnictwo nie potrafiło wyżywić kraju bez importu zboża. Ogromne wydatki pochłaniały zbrojenia w ramach wyścigu z USA (program „gwiezdnych wojen” Reagana) i wojna w Afganistanie (1979–1989). Spadek cen ropy w latach 80. pozbawił państwo dewiz. Katastrofa w Czarnobylu (1986) pokazała zacofanie i nieudolność systemu.\n\n'
     'W aspekcie politycznym kluczowe były reformy Michaiła Gorbaczowa, który od 1985 r. próbował ratować system przez pierestrojkę (przebudowę gospodarki) i głasnost (jawność). Głasnost pozwoliła ludziom mówić o zbrodniach Stalina i problemach kraju, co podważyło autorytet partii. W 1990 r. zniesiono kierowniczą rolę KPZR. Nieudany pucz komunistycznych twardogłowych w sierpniu 1991 r. ostatecznie skompromitował stare elity i wzmocnił Borysa Jelcyna.\n\n'
     'W aspekcie narodowościowym ZSRS był państwem wielu narodów, z których wiele zostało podbitych lub wcielonych siłą. Gdy głasnost dała swobodę, odżyły dążenia niepodległościowe. Litwa jako pierwsza ogłosiła niepodległość (marzec 1990), a krwawe wydarzenia w Wilnie (styczeń 1991) nie zatrzymały procesu. Po puczu niepodległość ogłaszały kolejne republiki, a w grudniu 1991 r. przywódcy Rosji, Ukrainy i Białorusi w Puszczy Białowieskiej rozwiązali ZSRS.\n\n'
     'Zwolennicy tezy podkreślają, że bez kryzysu gospodarczego Gorbaczow nie rozpocząłby reform. To prawda — gospodarka uruchomiła zmiany. Jednak kraje z równie słabą gospodarką, jak Korea Północna, przetrwały, bo nie zrezygnowały z terroru. O rozpadzie ZSRS zdecydowało połączenie liberalizacji politycznej i dążeń narodów.\n\n'
     'Na rozpad wpłynął też przykład Europy Środkowej z 1989 r.\n\n'
     'Podsumowując, słabość gospodarcza była punktem wyjścia, ale rozpad ZSRS był przede wszystkim wynikiem przemian politycznych i narodowościowych. Dlatego uważam tezę za tylko częściowo prawdziwą.',
     'Plan: stanowisko „częściowo” → gospodarczy (planowanie, zbrojenia, Afganistan, ropa, Czarnobyl) → polityczny (Gorbaczow, pierestrojka, głasnost, 1990, pucz 1991, Jelcyn) → narodowościowy (Litwa 1990, Wilno 1991, Puszcza Białowieska) → kontrargument (gospodarka uruchomiła zmiany; Korea Północna) → wniosek.\n\nTypowe błędy: pisanie, że ZSRS rozpadł się w 1989 r. (w 1989 r. upadły reżimy w Europie Środkowej, ZSRS — w grudniu 1991 r.).')),
]
